namespace Sunder.Package.Agent.Runtime;

internal static class AgentWorkerComposition
{
    internal static SunderWorkerOptions Create(IPackageContext context, ISunderRpcClient rpc,
        Func<ICollection<DeferredAgentRpcServiceHandler>, IReadOnlyList<SunderWorkerProviderRegistration>> createRegistrations)
    {
        ArgumentNullException.ThrowIfNull(context);
        ArgumentNullException.ThrowIfNull(rpc);
        ArgumentNullException.ThrowIfNull(createRegistrations);
        var services = new ServiceCollection();
        services.AddSingleton(context);
        services.AddSingleton(rpc);
        services.AddSingleton(AgentRpcCatalog.CreateDormant(rpc));
        new PackageModule().ConfigureRuntimeServices(services, context);
        var deferred = new List<DeferredAgentRpcServiceHandler>();
        services.AddSingleton(provider => new AgentWorkerLifecycle(provider, deferred));
        var serviceProvider = services.BuildServiceProvider(new ServiceProviderOptions
        {
            ValidateOnBuild = true,
            ValidateScopes = true,
        });
        try
        {
            var registrations = createRegistrations(deferred);
            var lifecycle = serviceProvider.GetRequiredService<AgentWorkerLifecycle>();
            return new SunderWorkerOptions(registrations)
            {
                Composition = new SunderWorkerComposition(serviceProvider, [lifecycle]),
            };
        }
        catch
        {
            serviceProvider.Dispose();
            throw;
        }
    }
}

