                services => AgentOwnerRuntimeRpc.CreateHandler(services.GetRequiredService<AgentOwnerRuntimeProvider>())),
        ]);

    internal static IReadOnlyList<AgentWorkerProviderDefinition> Definitions => ProviderDefinitions;

    internal static IReadOnlyList<SunderWorkerProviderRegistration> CreateRegistrations(ICollection<DeferredAgentRpcServiceHandler> deferred)
    {
        ArgumentNullException.ThrowIfNull(deferred);
        var registrations = new List<SunderWorkerProviderRegistration>(ProviderDefinitions.Count);
        foreach (var definition in ProviderDefinitions)
        {
            var handler = new DeferredAgentRpcServiceHandler(definition.ProviderId, definition.Descriptor, definition.CreateHandler);
