namespace Sunder.Package.Agent.Builder;

internal sealed class BuilderWorkerComposition : IAsyncDisposable
{
    private readonly IBuilderRuntimeLifetime _lifetime;
    internal BuilderWorkerComposition(ISunderRpcClient rpc)
    {
        var configured = BuilderWorkerBindings.Create(rpc);
        _lifetime = configured.Lifetime;
        Options = new(configured.Providers)
        {
            OnActivated = (_, token) => _lifetime.StartAsync(token),
            OnShutdown = (_, _) => DisposeAsync(),
        };
    }
    internal SunderWorkerOptions Options { get; }
    public ValueTask DisposeAsync() => _lifetime.DisposeAsync();
}

