public static class AgentBehaviorLoopRpc
{
    public const string ServiceId = "behavior-loop";

    public static ISunderRpcServiceHandler CreateHandler(IAgentBehaviorLoop loop, AgentRpcCatalog rpcCatalog)
        => AgentRpcServiceHandler.Create(AgentRpcContractDescriptors.Get(AgentRpcContractIds.BehaviorLoop))
            .AddUnary<AgentRpcEmpty, AgentBehaviorLoopDescriptor>(ServiceId, "describe", (_, _, _) => ValueTask.FromResult(loop.Descriptor))
            .AddUnary<BehaviorLoopRunRequest, AgentBehaviorLoopResult>(ServiceId, "run", (_, request, token) =>
                loop.RunAsync(request.Context, new AgentBehaviorLoopRuntimeRpcClient(rpcCatalog, request.InvocationId, request.RunControl), token))
            .Build();
}

public sealed class AgentBehaviorLoopRpcClient(
    ISunderRpcClient client,
    SunderRpcProviderSnapshot provider,
    AgentRunControlRegistry runControls,
    AgentRpcCatalog rpcCatalog) : IAgentBehaviorLoop
{
    private AgentBehaviorLoopDescriptor? _descriptor;

    public AgentBehaviorLoopDescriptor Descriptor
        => _descriptor ??= AgentRpcServiceHandler.InvokeAsync<AgentRpcEmpty, AgentBehaviorLoopDescriptor>(
            client, provider.Endpoint, AgentBehaviorLoopRpc.ServiceId, "describe", new AgentRpcEmpty()).AsTask().GetAwaiter().GetResult();

    public async ValueTask<AgentBehaviorLoopResult> RunAsync(
        AgentBehaviorLoopContext context,
        IAgentBehaviorLoopRuntime runtime,
        CancellationToken cancellationToken = default)
    {
        var runControl = rpcCatalog.GetServiceReferences(AgentRpcServices.RunControls)
            .FirstOrDefault(static reference =>
                string.Equals(reference.PackageId, "sunder.package.agent", StringComparison.Ordinal)
                && string.Equals(reference.ProviderId, AgentRunControlRpc.ProviderId, StringComparison.Ordinal))
            ?? throw new SunderRpcException(new SunderRpcError(
                SunderRpcErrorKind.Unavailable,
                "agent.run-control.unavailable",
                "The Agent run-control provider is unavailable."));
        if (!runControl.TryAcquire(out var runControlLease))
        {
            throw new SunderRpcException(new SunderRpcError(
                SunderRpcErrorKind.StaleEndpoint,
                "agent.run-control.stale",
                "The Agent run-control provider activation is stale."));
        }
        using (runControlLease)
        {
            using var registration = runControls.Open(runtime, provider.PackageId, out var invocationId);
            using var invocation = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken, runControlLease.RetirementToken);
            return await AgentRpcServiceHandler.InvokeAsync<BehaviorLoopRunRequest, AgentBehaviorLoopResult>(
                    client,
                    provider.Endpoint,
                    AgentBehaviorLoopRpc.ServiceId,
                    "run",
                    new(invocationId, runControl.ToHandle(), context),
                    AgentRpcServiceHandler.CreateExtendedCallOptions(),
                    invocation.Token)
                .ConfigureAwait(false);
        }
    }
}

public static class AgentRunControlRpc
{
    public const string ProviderId = "agent.run.control";
    public const string ServiceId = "run-control";

    public static ISunderRpcServiceHandler CreateHandler(AgentRunControlRegistry registry)
    {
        return AgentRpcServiceHandler.Create(AgentRpcContractDescriptors.Get(AgentRpcContractIds.RunControl))
            .AddUnary<RunControlInvocation, bool>(ServiceId, "is-current", (call, request, _) => ValueTask.FromResult(Resolve(registry, call, request).IsCurrentRun()))
            .AddUnary<RunControlInvocation, IReadOnlyList<AgentTurnRecord>>(ServiceId, "list-turns", (call, request, _) => ValueTask.FromResult(Resolve(registry, call, request).ListTurns()))
            .AddUnary<RunControlRecentTurnsRequest, IReadOnlyList<AgentTurnRecord>>(ServiceId, "list-recent-turns", (call, request, _) => ValueTask.FromResult(Resolve(registry, call, request.Invocation).ListRecentTurns(request.Limit)))
            .AddUnary<RunControlInvocation, AgentBehaviorInstructionContext>(ServiceId, "build-instruction-context", (call, request, token) => Resolve(registry, call, request).BuildInstructionContextAsync(token))
            .AddUnary<RunControlSessionProjectionRequest, AgentRpcEmpty>(ServiceId, "select-session-context", (call, request, _) =>
            {
                RequireCapability<IAgentSessionContextSelectionRuntime>(Resolve(registry, call, request.Invocation), "session context selection")
                    .SelectSessionContextProjection(request.Projection);
                return ValueTask.FromResult(new AgentRpcEmpty());
            })
            .AddUnary<RunControlActivityRequest, AgentRpcEmpty>(ServiceId, "report-activity", (call, request, _) =>
            {
                RequireCapability<IAgentRunActivitySink>(Resolve(registry, call, request.Invocation), "run activity")
                    .ReportRunActivity(request.Kind, request.Text);
                return ValueTask.FromResult(new AgentRpcEmpty());
            })
            .AddUnary<RunControlInvocation, AgentRunBudgetState>(ServiceId, "get-run-budget", (call, request, _) => ValueTask.FromResult(
                RequireCapability<IAgentRunBudgetRuntime>(Resolve(registry, call, request), "run budget").GetRunBudgetState()))
            .AddUnary<RunControlBudgetChargeRequest, AgentRunBudgetState>(ServiceId, "charge-run-budget", (call, request, _) => ValueTask.FromResult(
                RequireCapability<IAgentRunBudgetRuntime>(Resolve(registry, call, request.Invocation), "run budget").ChargeRunBudget(request.Charge)))
            .AddUnary<RunControlPromptContextRequest, AgentRpcEmpty>(ServiceId, "acknowledge-prompt-context", async (call, request, token) =>
            {
                if (Resolve(registry, call, request.Invocation) is not IAgentPromptContextAcknowledgmentRuntime runtime)
                {
                    throw new SunderRpcException(new SunderRpcError(
                        SunderRpcErrorKind.Domain,
                        "agent.run-control.prompt-context-acknowledgment-unavailable",
                        "The Agent run-control provider cannot acknowledge prompt context."));
                }
                await runtime.AcknowledgePromptContextAsync(request.Blocks, token).ConfigureAwait(false);
                return new AgentRpcEmpty();
            })
            .AddUnary<RunControlInvocation, AgentRpcEmpty>(ServiceId, "discard-prompt-context", (call, request, _) =>
            {
                if (Resolve(registry, call, request) is IAgentPromptContextAcknowledgmentRuntime runtime)
                {
                    runtime.DiscardPromptContextAcknowledgment();
                }
                return ValueTask.FromResult(new AgentRpcEmpty());
            })
            .AddUnary<RunControlInvocation, IReadOnlyList<AgentToolDescriptor>>(ServiceId, "list-ready-tools", async (call, request, token) =>
                (await Resolve(registry, call, request).ListReadyToolsAsync(token).ConfigureAwait(false)).Select(static tool => tool.Descriptor).ToArray())
            .AddUnary<RunControlCheckpointRequest, AgentRunCheckpointRecord>(ServiceId, "save-checkpoint", (call, request, _) => ValueTask.FromResult(Resolve(registry, call, request.Invocation).SaveCheckpoint(request.Status, request.Summary)))
            .AddUnary<RunControlLogRequest, AgentRpcEmpty>(ServiceId, "log-event", (call, request, _) =>
            {
                Resolve(registry, call, request.Invocation).LogEvent(request.Level, request.EventName, request.Message, request.ElapsedMilliseconds, request.Attributes?.ToDictionary(static pair => pair.Key, static pair => (object?)pair.Value, StringComparer.Ordinal));
                return ValueTask.FromResult(new AgentRpcEmpty());
            })
            .AddUnary<RunControlAssistantTurnRequest, AgentTurnRecord>(ServiceId, "upsert-assistant-turn", (call, request, _) => ValueTask.FromResult(Resolve(registry, call, request.Invocation).UpsertAssistantTurn(request.AssistantTurn, request.Content)))
            .AddUnary<RunControlCompleteTurnRequest, AgentTurnRecord>(ServiceId, "complete-assistant-turn", (call, request, _) => ValueTask.FromResult(Resolve(registry, call, request.Invocation).CompleteAssistantTurn(request.AssistantTurn)))
            .AddUnary<RunControlLifecycleRequest, AgentRpcEmpty>(ServiceId, "publish-lifecycle", async (call, request, token) =>
            {
                await Resolve(registry, call, request.Invocation).PublishLifecycleEventAsync(request.Kind, request.Status, request.TriggerTurn, request.Checkpoint, request.IsInterrupted, token).ConfigureAwait(false);
                return new AgentRpcEmpty();
            })
            .AddUnary<RunControlToolRequest, AgentToolCallOutcome>(ServiceId, "invoke-tool", (call, request, token) => Resolve(registry, call, request.Invocation).InvokeToolAsync(request.ToolCall, request.AssistantTurn, token))
            .AddUnary<RunControlToolsRequest, IReadOnlyList<AgentToolCallOutcome>>(ServiceId, "invoke-tools", (call, request, token) => Resolve(registry, call, request.Invocation).InvokeToolsAsync(request.ToolCalls, request.AssistantTurn, token))
            .AddUnary<RunControlDefaultLoopRequest, AgentBehaviorLoopResult>(ServiceId, "run-default", (call, request, token) =>
            {
                var runtime = Resolve(registry, call, request.Invocation);
                return runtime is IAgentInnerBehaviorLoopRuntime inner
                    ? inner.RunDefaultLoopAsync(request.Context, token)
                    : ValueTask.FromException<AgentBehaviorLoopResult>(new SunderRpcException(new SunderRpcError(
                        SunderRpcErrorKind.Domain,
                        "agent.run-control.default-loop-unavailable",
                        "The default behavior loop is unavailable.")));
            })
            .AddStream<RunControlChatRequest, AgentChatStreamEvent>(ServiceId, "stream-chat", (call, request, token) => StreamChatAsync(
                Resolve(registry, call, request.Invocation),
                request,
                call,
                token))
            .Build();
    }

    private static IAgentBehaviorLoopRuntime Resolve(
        AgentRunControlRegistry registry,
        SunderRpcInvocationContext call,
        RunControlInvocation invocation)
        => registry.Resolve(invocation.InvocationId, call.CallerPackageId);

    private static TCapability RequireCapability<TCapability>(IAgentBehaviorLoopRuntime runtime, string displayName)
        where TCapability : class
        => runtime as TCapability
           ?? throw new SunderRpcException(new SunderRpcError(
               SunderRpcErrorKind.Domain,
               "agent.run-control.capability-unavailable",
               $"The Agent run-control provider does not support {displayName}."));

    private static async IAsyncEnumerable<AgentChatStreamEvent> StreamChatAsync(
        IAgentBehaviorLoopRuntime runtime,
        RunControlChatRequest request,
        SunderRpcInvocationContext context,
        [EnumeratorCancellation] CancellationToken cancellationToken)
    {
        IChatClient? chat = null;
        IAsyncEnumerator<ChatResponseUpdate>? updates = null;
        AgentChatProviderException? providerException = null;
        Exception? streamException = null;
        Exception? cleanupException = null;
        try
        {
            try
            {
                chat = await runtime.CreateChatClientAsync(
                    new AgentChatClientContext(
                        request.Context.ProviderId,
                        request.Context.ModelId,
                        CorrelationAttributes: request.Context.CorrelationAttributes?.ToDictionary(static pair => pair.Key, static pair => (object?)pair.Value, StringComparer.Ordinal)),
                    cancellationToken).ConfigureAwait(false);
                var messages = await AgentChatWireMapper.ToChatMessagesAsync(
                    request.Messages,
                    context,
                    cancellationToken).ConfigureAwait(false);
                updates = chat.GetStreamingResponseAsync(
                        messages,
                        AgentChatWireMapper.ToChatOptions(request.Options),
                        cancellationToken)
                    .GetAsyncEnumerator(cancellationToken);
            }
            catch (AgentChatProviderException exception)
            {
                providerException = exception;
            }
            catch (Exception exception)
            {
                streamException = exception;
            }

            while (providerException is null && streamException is null && updates is not null)
            {
                AgentChatStreamEvent? mappedUpdate = null;
                var hasNext = false;
                try
                {
                    hasNext = await updates.MoveNextAsync().ConfigureAwait(false);
                    if (hasNext)
                    {
                        mappedUpdate = AgentChatWireMapper.FromUpdate(updates.Current);
                    }
                }
                catch (AgentChatProviderException exception)
                {
                    providerException = exception;
                }
                catch (Exception exception)
                {
                    streamException = exception;
                }

                if (!hasNext || providerException is not null || streamException is not null)
                {
                    break;
                }

                yield return mappedUpdate!;
            }
        }
        finally
        {
            if (updates is not null)
            {
                try
                {
                    await updates.DisposeAsync().ConfigureAwait(false);
                }
                catch (AgentChatProviderException exception)
                {
                    providerException ??= exception;
                }
                catch (Exception exception)
                {
                    cleanupException ??= exception;
                }
            }

            if (chat is not null)
            {
                try
                {
                    chat.Dispose();
                }
                catch (AgentChatProviderException exception)
                {
                    providerException ??= exception;
                }
                catch (Exception exception)
                {
                    cleanupException ??= exception;
                }
            }
        }

        cancellationToken.ThrowIfCancellationRequested();
        if (streamException is not null)
        {
            ExceptionDispatchInfo.Capture(streamException).Throw();
        }
        if (providerException is not null)
        {
            yield return AgentChatStreamEvent.Error(
                providerException.ErrorCode ?? "provider-error",
                providerException.Message,
                providerException.Content,
                providerException.FailureKind);
        }
        else if (cleanupException is not null)
        {
            ExceptionDispatchInfo.Capture(cleanupException).Throw();
        }
    }
}

public sealed class AgentRunControlRpcClient(ISunderRpcClient client, SunderRpcEndpointReference endpoint)
{
    internal ValueTask<TResponse> InvokeAsync<TRequest, TResponse>(string methodId, TRequest request, CancellationToken cancellationToken = default)
        where TRequest : notnull
        where TResponse : notnull
        => AgentRpcServiceHandler.InvokeAsync<TRequest, TResponse>(client, endpoint, AgentRunControlRpc.ServiceId, methodId, request, cancellationToken);

    internal ValueTask<TResponse> InvokeExtendedAsync<TRequest, TResponse>(string methodId, TRequest request, CancellationToken cancellationToken = default)
        where TRequest : notnull
        where TResponse : notnull
        => AgentRpcServiceHandler.InvokeAsync<TRequest, TResponse>(
            client,
            endpoint,
            AgentRunControlRpc.ServiceId,
            methodId,
            request,
            AgentRpcServiceHandler.CreateExtendedCallOptions(),
            cancellationToken);

    internal ValueTask<ISunderRpcCallScope> CreateCallScopeAsync(CancellationToken cancellationToken)
        => client.CreateCallScopeAsync(cancellationToken: cancellationToken);

    internal ValueTask<SunderRpcContentReference> RegisterContentAsync(
        ISunderRpcCallScope scope,
        DataContent content,
        CancellationToken cancellationToken)
        => AgentChatWireMapper.RegisterContentAsync(scope, endpoint, content, cancellationToken);

    internal IAsyncEnumerable<AgentChatStreamEvent> StreamChatAsync(
        ISunderRpcClient? invocationClient,
        RunControlChatRequest request,
        CancellationToken cancellationToken)
        => AgentRpcServiceHandler.SubscribeAsync<RunControlChatRequest, AgentChatStreamEvent>(
            invocationClient ?? client,
            endpoint,
            AgentRunControlRpc.ServiceId,
            "stream-chat",
            request,
            cancellationToken);
}

internal sealed class AgentBehaviorLoopRuntimeRpcClient :
    IAgentBehaviorLoopRuntime,
    IAgentInnerBehaviorLoopRuntime,
    IAgentSessionContextSelectionRuntime,
    IAgentRunActivitySink,
    IAgentRunBudgetRuntime,
    IAgentPromptContextAcknowledgmentRuntime
{
    private readonly AgentRpcReference<AgentRunControlRpcClient> _runControl;
    private readonly Guid _invocationId;

    internal AgentBehaviorLoopRuntimeRpcClient(
        AgentRpcCatalog catalog,
        Guid invocationId,
        AgentRpcProviderHandle runControl)
    {
        _runControl = catalog.GetServiceReference(AgentRpcServices.RunControls, runControl);
        _invocationId = invocationId;
    }

    private RunControlInvocation Invocation => new(_invocationId);

    public bool IsCurrentRun() => Invoke<RunControlInvocation, bool>("is-current", Invocation);
    public IReadOnlyList<AgentTurnRecord> ListTurns() => Invoke<RunControlInvocation, IReadOnlyList<AgentTurnRecord>>("list-turns", Invocation);
    public IReadOnlyList<AgentTurnRecord> ListRecentTurns(int limit) => Invoke<RunControlRecentTurnsRequest, IReadOnlyList<AgentTurnRecord>>("list-recent-turns", new(Invocation, limit));
    public ValueTask<AgentBehaviorInstructionContext> BuildInstructionContextAsync(CancellationToken cancellationToken = default) => InvokeAsync<RunControlInvocation, AgentBehaviorInstructionContext>("build-instruction-context", Invocation, cancellationToken);

    public void SelectSessionContextProjection(AgentSessionPromptProjection projection)
        => _ = Invoke<RunControlSessionProjectionRequest, AgentRpcEmpty>("select-session-context", new(Invocation, projection));

    public void ReportRunActivity(AgentRunActivityKind kind, string text)
        => _ = Invoke<RunControlActivityRequest, AgentRpcEmpty>("report-activity", new(Invocation, kind, text));

    public AgentRunBudgetState GetRunBudgetState()
        => Invoke<RunControlInvocation, AgentRunBudgetState>("get-run-budget", Invocation);

    public AgentRunBudgetState ChargeRunBudget(AgentRunBudgetCharge charge)
        => Invoke<RunControlBudgetChargeRequest, AgentRunBudgetState>("charge-run-budget", new(Invocation, charge));

    public async ValueTask AcknowledgePromptContextAsync(
        IReadOnlyList<AgentPromptContextReceiptBlock> blocks,
        CancellationToken cancellationToken)
        => _ = await InvokeAsync<RunControlPromptContextRequest, AgentRpcEmpty>(
            "acknowledge-prompt-context",
            new(Invocation, blocks),
            cancellationToken).ConfigureAwait(false);

    public void DiscardPromptContextAcknowledgment()
        => _ = Invoke<RunControlInvocation, AgentRpcEmpty>("discard-prompt-context", Invocation);

    public async ValueTask<IReadOnlyList<AgentRuntimeTool>> ListReadyToolsAsync(CancellationToken cancellationToken = default)
    {
        var descriptors = await InvokeAsync<RunControlInvocation, IReadOnlyList<AgentToolDescriptor>>("list-ready-tools", Invocation, cancellationToken).ConfigureAwait(false);
        return descriptors.Select(static descriptor => new AgentRuntimeTool(
            descriptor,
            AIFunctionFactory.CreateDeclaration(
                descriptor.ToolId,
                descriptor.Description,
                string.IsNullOrWhiteSpace(descriptor.ArgumentsJsonSchema)
                    ? JsonSerializer.SerializeToElement(new { type = "object", properties = new { }, additionalProperties = false })
                    : JsonDocument.Parse(descriptor.ArgumentsJsonSchema).RootElement.Clone()))).ToArray();
    }

    public ValueTask<IChatClient> CreateChatClientAsync(AgentChatClientContext context, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        var wire = new RunControlChatContext(
            context.ProviderId,
            context.ModelId,
            context.CorrelationAttributes?.ToDictionary(static pair => pair.Key, static pair => JsonSerializer.SerializeToElement(pair.Value), StringComparer.Ordinal));
        return ValueTask.FromResult<IChatClient>(new AgentRunControlChatClient(this, wire));
    }

    public AgentRunCheckpointRecord SaveCheckpoint(AgentRunStatus status, string? summary) => Invoke<RunControlCheckpointRequest, AgentRunCheckpointRecord>("save-checkpoint", new(Invocation, status, summary));

    public void LogEvent(PackageLogLevel level, string eventName, string message, long? elapsedMilliseconds = null, IReadOnlyDictionary<string, object?>? attributes = null, Exception? exception = null)
        => _ = Invoke<RunControlLogRequest, AgentRpcEmpty>("log-event", new(
            Invocation,
            level,
            eventName,
            message,
            elapsedMilliseconds,
            attributes?.ToDictionary(static pair => pair.Key, static pair => JsonSerializer.SerializeToElement(pair.Value), StringComparer.Ordinal),
            exception?.GetType().FullName,
            exception?.Message));

    public AgentTurnRecord UpsertAssistantTurn(AgentTurnRecord? assistantTurn, string content) => Invoke<RunControlAssistantTurnRequest, AgentTurnRecord>("upsert-assistant-turn", new(Invocation, assistantTurn, content));
    public AgentTurnRecord CompleteAssistantTurn(AgentTurnRecord assistantTurn) => Invoke<RunControlCompleteTurnRequest, AgentTurnRecord>("complete-assistant-turn", new(Invocation, assistantTurn));

    public async ValueTask PublishLifecycleEventAsync(AgentLifecycleEventKind kind, AgentRunStatus status, AgentTurnRecord? triggerTurn = null, AgentRunCheckpointRecord? checkpoint = null, bool isInterrupted = false, CancellationToken cancellationToken = default)
        => _ = await InvokeAsync<RunControlLifecycleRequest, AgentRpcEmpty>("publish-lifecycle", new(Invocation, kind, status, triggerTurn, checkpoint, isInterrupted), cancellationToken).ConfigureAwait(false);

    public ValueTask<AgentToolCallOutcome> InvokeToolAsync(AgentToolCallRequest toolCall, AgentTurnRecord? assistantTurn, CancellationToken cancellationToken = default)
        => InvokeExtendedAsync<RunControlToolRequest, AgentToolCallOutcome>("invoke-tool", new(Invocation, toolCall, assistantTurn), cancellationToken);

    public ValueTask<IReadOnlyList<AgentToolCallOutcome>> InvokeToolsAsync(IReadOnlyList<AgentToolCallRequest> toolCalls, AgentTurnRecord? assistantTurn, CancellationToken cancellationToken = default)
        => InvokeExtendedAsync<RunControlToolsRequest, IReadOnlyList<AgentToolCallOutcome>>("invoke-tools", new(Invocation, toolCalls, assistantTurn), cancellationToken);

    public ValueTask<AgentBehaviorLoopResult> RunDefaultLoopAsync(AgentBehaviorLoopContext context, CancellationToken cancellationToken = default)
        => InvokeExtendedAsync<RunControlDefaultLoopRequest, AgentBehaviorLoopResult>("run-default", new(Invocation, context), cancellationToken);

    internal IAsyncEnumerable<AgentChatStreamEvent> StreamChatAsync(
        RunControlChatContext context,
        IEnumerable<ChatMessage> messages,
        ChatOptions? options,
        CancellationToken cancellationToken)
        => WithControlStream(
            control => StreamChatAsync(control, context, messages, options, cancellationToken),
            cancellationToken);

    private async IAsyncEnumerable<AgentChatStreamEvent> StreamChatAsync(
        AgentRunControlRpcClient control,
        RunControlChatContext context,
        IEnumerable<ChatMessage> messages,
        ChatOptions? options,
        [EnumeratorCancellation] CancellationToken cancellationToken)
    {
        ISunderRpcCallScope? scope = null;
        try
        {
            var mappedMessages = await AgentChatWireMapper.FromChatMessagesAsync(
                messages,
                RegisterContentAsync,
                cancellationToken).ConfigureAwait(false);
            var request = new RunControlChatRequest(
                Invocation,
                context,
                mappedMessages,
                AgentChatWireMapper.FromChatOptions(options));
            await foreach (var item in control.StreamChatAsync(scope, request, cancellationToken)
                               .WithCancellation(cancellationToken).ConfigureAwait(false))
            {
                yield return item;
            }
        }
        finally
        {
            if (scope is not null)
            {
                await scope.DisposeAsync().ConfigureAwait(false);
            }
        }

        async ValueTask<SunderRpcContentReference> RegisterContentAsync(
            DataContent content,
            CancellationToken token)
        {
            scope ??= await control.CreateCallScopeAsync(token).ConfigureAwait(false);
            return await control.RegisterContentAsync(scope, content, token).ConfigureAwait(false);
        }
    }

    private TResponse Invoke<TRequest, TResponse>(string methodId, TRequest request) where TRequest : notnull where TResponse : notnull
        => InvokeAsync<TRequest, TResponse>(methodId, request).AsTask().GetAwaiter().GetResult();

    private async ValueTask<TResponse> InvokeAsync<TRequest, TResponse>(string methodId, TRequest request, CancellationToken cancellationToken = default)
        where TRequest : notnull
        where TResponse : notnull
    {
        if (!_runControl.TryAcquire(out var lease))
        {
            throw new SunderRpcException(new SunderRpcError(SunderRpcErrorKind.StaleEndpoint, "agent.run-control.stale", "The Agent run-control provider activation is stale."));
        }
        using (lease)
        using (var invocation = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken, lease.RetirementToken))
        {
            return await lease.Service.InvokeAsync<TRequest, TResponse>(methodId, request, invocation.Token).ConfigureAwait(false);
        }
    }

    private async ValueTask<TResponse> InvokeExtendedAsync<TRequest, TResponse>(string methodId, TRequest request, CancellationToken cancellationToken = default)
        where TRequest : notnull
        where TResponse : notnull
    {
        if (!_runControl.TryAcquire(out var lease))
        {
            throw new SunderRpcException(new SunderRpcError(SunderRpcErrorKind.StaleEndpoint, "agent.run-control.stale", "The Agent run-control provider activation is stale."));
        }
        using (lease)
        using (var invocation = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken, lease.RetirementToken))
        {
            return await lease.Service.InvokeExtendedAsync<TRequest, TResponse>(methodId, request, invocation.Token).ConfigureAwait(false);
        }
    }

    private async IAsyncEnumerable<AgentChatStreamEvent> WithControlStream(
        Func<AgentRunControlRpcClient, IAsyncEnumerable<AgentChatStreamEvent>> subscribe,
        [EnumeratorCancellation] CancellationToken cancellationToken)
    {
        if (!_runControl.TryAcquire(out var lease))
        {
            throw new SunderRpcException(new SunderRpcError(SunderRpcErrorKind.StaleEndpoint, "agent.run-control.stale", "The Agent run-control provider activation is stale."));
        }
        using (lease)
        using (var invocation = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken, lease.RetirementToken))
        {
            await foreach (var item in subscribe(lease.Service).WithCancellation(invocation.Token).ConfigureAwait(false)) yield return item;
        }
    }
}

internal sealed class AgentRunControlChatClient(AgentBehaviorLoopRuntimeRpcClient runtime, RunControlChatContext context) : IChatClient
{
    public async Task<ChatResponse> GetResponseAsync(IEnumerable<ChatMessage> messages, ChatOptions? options = null, CancellationToken cancellationToken = default)
        => await GetStreamingResponseAsync(messages, options, cancellationToken).ToChatResponseAsync(cancellationToken).ConfigureAwait(false);

    public async IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(IEnumerable<ChatMessage> messages, ChatOptions? options = null, [EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        await foreach (var item in runtime.StreamChatAsync(
                           context,
                           messages,
                           options,
