            .AddNullableUnary<AgentExecutionTargetContextWire, string>(ServiceId, "configuration-generation", async (_, request, token) => await target.GetConfigurationGenerationAsync(request.ToContext(), token).ConfigureAwait(false))
            .AddUnary<AgentExecutionTargetContextWire, AgentExecutionTargetReadiness>(ServiceId, "readiness", (_, request, token) => target.GetReadinessAsync(request.ToContext(), token))
            .AddUnary<AgentExecutionTargetContextWire, AgentExecutionShellDescriptor>(ServiceId, "shell", (_, request, token) => target.GetShellAsync(request.ToContext(), token))
            .AddUnary<ExecutionPathRequest, AgentResolvedResourceWire>(ServiceId, "resolve-file", async (_, request, token) => AgentResolvedResourceWire.FromResource(
                await target.ResolveFileResourceAsync(request.Context.ToContext(), request.Path, token).ConfigureAwait(false)))
            .AddUnary<ExecutionShellRequest, AgentShellCommandResult>(ServiceId, "execute-shell", (_, request, token) => target.ExecuteShellAsync(request.Context.ToContext(), request.Request, token))
            .AddUnary<ExecutionFileReadRequest, AgentFileReadResult>(ServiceId, "read-file", (_, request, token) => target.ReadFileAsync(request.Context.ToContext(), request.Request, token))
            .AddUnary<ExecutionFileWriteRequest, AgentFileMutationResultWire>(ServiceId, "write-file", async (_, request, token) => AgentFileMutationResultWire.FromResult(
                await target.WriteFileAsync(request.Context.ToContext(), request.Request, token).ConfigureAwait(false)))
            .AddUnary<ExecutionFileDeleteRequest, AgentFileMutationResultWire>(ServiceId, "delete-file", async (_, request, token) => AgentFileMutationResultWire.FromResult(
                await target.DeleteFileAsync(request.Context.ToContext(), request.Request, token).ConfigureAwait(false)))
            .AddUnary<ExecutionProcessRequest, AgentShellCommandResult>(ServiceId, "execute-process", (_, request, token) => Require<IAgentProcessExecutionTarget>(target, descriptor, AgentExecutionFacetIds.ProcessExecution).ExecuteProcessAsync(request.Context.ToContext(), request.Request, token))
            .AddUnary<ExecutionResourcesRequest, IReadOnlyList<AgentResolvedExecutionResource>>(ServiceId, "resolve-resources", (_, request, token) => Require<IAgentExecutionResourceResolver>(target, descriptor, AgentExecutionFacetIds.ResourceResolution).ResolveResourcesAsync(request.Context.ToContext(), request.Resources, token))
            .AddUnary<AgentExecutionTargetContextWire, AgentResourceAuthorityValidation>(ServiceId, "validate-resource-authority", (_, request, token) => Require<IAgentResourceAuthorityExecutionTarget>(target, descriptor, AgentExecutionFacetIds.ResourceAuthority).ValidateResourceAuthorityAsync(request.ToContext(), token))
            .AddUnary<ResourceCapabilitiesRequest, AgentRpcEmpty>(ServiceId, "release-resource-authority", (_, request, _) =>
            {
                Require<IAgentResourceAuthorityExecutionTarget>(target, descriptor, AgentExecutionFacetIds.ResourceAuthority).ReleaseResourceAuthority(request.Capabilities);
                return ValueTask.FromResult(new AgentRpcEmpty());
            })
            .AddUnary<AgentExecutionTargetContextWire, AgentExecutionScopeDescriptor>(ServiceId, "execution-scope", (_, request, token) => Require<IAgentExecutionScopeProvider>(target, descriptor, AgentExecutionFacetIds.ExecutionScope).GetExecutionScopeAsync(request.ToContext(), token))
            .AddUnary<ExecutionPathRequest, AgentExecutionPathMapping>(ServiceId, "map-path", (_, request, token) => Require<IAgentExecutionPathMapper>(target, descriptor, AgentExecutionFacetIds.PathMapping).MapToHostPathAsync(request.Context.ToContext(), request.Path, token))
            .AddUnary<AgentExecutionTargetContextWire, IReadOnlyList<string>>(ServiceId, "list-path", (_, request, token) => Require<IAgentExecutionPathEnvironment>(target, descriptor, AgentExecutionFacetIds.PathEnvironment).ListPathEntriesAsync(request.ToContext(), token))
            .AddUnary<ExecutionPathRequest, AgentRpcEmpty>(ServiceId, "add-path", async (_, request, token) =>
            {
                await Require<IAgentExecutionPathEnvironment>(target, descriptor, AgentExecutionFacetIds.PathEnvironment).AddPathEntryAsync(request.Context.ToContext(), request.Path, token).ConfigureAwait(false);
                return new AgentRpcEmpty();
            })
            .AddUnary<ExecutionFileSearchRequest, AgentFileSearchResult>(ServiceId, "structured-file-search", (_, request, token) => Require<IAgentStructuredFileSearchExecutionTarget>(target, descriptor, AgentExecutionFacetIds.StructuredFileSearch).ExecuteFileSearchAsync(request.Context.ToContext(), request.Request, token))
            .AddUnary<ExecutionInstructionDiscoveryRequest, AgentScopedInstructionDiscoveryResult>(ServiceId, "discover-instructions", (_, request, token) => Require<IAgentScopedInstructionDiscoveryTarget>(target, descriptor, AgentExecutionFacetIds.ScopedInstructionDiscovery).DiscoverScopedInstructionsAsync(request.Context.ToContext(), request.Request, token))
            .Build();
    }

    public static bool SupportsFacet(IAgentExecutionTarget target, string facetId)
    {
        ArgumentNullException.ThrowIfNull(target);
        ArgumentException.ThrowIfNullOrWhiteSpace(facetId);
        if (target is AgentExecutionTargetRpcClient || target.Descriptor.Facets.Count > 0)
        {
            return target.Descriptor.SupportsFacet(facetId);
        }

        return facetId switch
        {
            AgentExecutionFacetIds.ProcessExecution => target is IAgentProcessExecutionTarget,
            AgentExecutionFacetIds.ResourceResolution => target is IAgentExecutionResourceResolver,
            AgentExecutionFacetIds.ResourceAuthority => target is IAgentResourceAuthorityExecutionTarget,
            AgentExecutionFacetIds.ExecutionScope => target is IAgentExecutionScopeProvider,
            AgentExecutionFacetIds.PathMapping => target is IAgentExecutionPathMapper,
            AgentExecutionFacetIds.PathEnvironment => target is IAgentExecutionPathEnvironment,
            AgentExecutionFacetIds.RangedFileRead => target is IAgentRangedFileExecutionTarget,
            AgentExecutionFacetIds.StructuredFileSearch => target is IAgentStructuredFileSearchExecutionTarget,
            AgentExecutionFacetIds.ScopedInstructionDiscovery => target is IAgentScopedInstructionDiscoveryTarget,
            _ => false,
        };
    }

    private static AgentExecutionTargetDescriptor WithFacets(IAgentExecutionTarget target)
    {
        var facets = target.Descriptor.Facets.Count > 0
            ? target.Descriptor.Facets
            : new[]
            {
                SupportsFacet(target, AgentExecutionFacetIds.ProcessExecution) ? AgentExecutionFacetIds.ProcessExecution : null,
                SupportsFacet(target, AgentExecutionFacetIds.ResourceResolution) ? AgentExecutionFacetIds.ResourceResolution : null,
                SupportsFacet(target, AgentExecutionFacetIds.ResourceAuthority) ? AgentExecutionFacetIds.ResourceAuthority : null,
                SupportsFacet(target, AgentExecutionFacetIds.ExecutionScope) ? AgentExecutionFacetIds.ExecutionScope : null,
                SupportsFacet(target, AgentExecutionFacetIds.PathMapping) ? AgentExecutionFacetIds.PathMapping : null,
                SupportsFacet(target, AgentExecutionFacetIds.PathEnvironment) ? AgentExecutionFacetIds.PathEnvironment : null,
                SupportsFacet(target, AgentExecutionFacetIds.RangedFileRead) ? AgentExecutionFacetIds.RangedFileRead : null,
                SupportsFacet(target, AgentExecutionFacetIds.StructuredFileSearch) ? AgentExecutionFacetIds.StructuredFileSearch : null,
                SupportsFacet(target, AgentExecutionFacetIds.ScopedInstructionDiscovery) ? AgentExecutionFacetIds.ScopedInstructionDiscovery : null,
            }.Where(static facet => facet is not null).Select(static facet => facet!).ToArray();
        return target.Descriptor with { Facets = facets };
    }

    private static TFacet Require<TFacet>(IAgentExecutionTarget target, AgentExecutionTargetDescriptor descriptor, string facetId)
        where TFacet : class
        => descriptor.SupportsFacet(facetId) && target is TFacet facet
            ? facet
            : throw new SunderRpcException(new SunderRpcError(
                SunderRpcErrorKind.Domain,
                "agent.execution.facet-unavailable",
                $"Execution target facet '{facetId}' is unavailable."));
}

