    public ValueTask<IReadOnlyList<AgentResolvedExecutionResource>> ResolveResourcesAsync(AgentExecutionTargetContext context, IReadOnlyList<AgentExecutionResourceDescriptor> resources, CancellationToken cancellationToken = default) => InvokeFacetAsync<ExecutionResourcesRequest, IReadOnlyList<AgentResolvedExecutionResource>>(AgentExecutionFacetIds.ResourceResolution, "resolve-resources", new(AgentExecutionTargetContextWire.FromContext(context), resources), cancellationToken);
    public ValueTask<AgentResourceAuthorityValidation> ValidateResourceAuthorityAsync(AgentExecutionTargetContext context, CancellationToken cancellationToken = default) => InvokeFacetAsync<AgentExecutionTargetContextWire, AgentResourceAuthorityValidation>(AgentExecutionFacetIds.ResourceAuthority, "validate-resource-authority", AgentExecutionTargetContextWire.FromContext(context), cancellationToken);
    public void ReleaseResourceAuthority(IReadOnlyList<string> resourceCapabilities) => _ = InvokeFacet<ResourceCapabilitiesRequest, AgentRpcEmpty>(AgentExecutionFacetIds.ResourceAuthority, "release-resource-authority", new(resourceCapabilities));
