    public ValueTask<AgentExecutionPathMapping> MapToHostPathAsync(AgentExecutionTargetContext context, string executionPath, CancellationToken cancellationToken = default) => InvokeFacetAsync<ExecutionPathRequest, AgentExecutionPathMapping>(AgentExecutionFacetIds.PathMapping, "map-path", new(AgentExecutionTargetContextWire.FromContext(context), executionPath), cancellationToken);
    public ValueTask<IReadOnlyList<string>> ListPathEntriesAsync(AgentExecutionTargetContext context, CancellationToken cancellationToken = default) => InvokeFacetAsync<AgentExecutionTargetContextWire, IReadOnlyList<string>>(AgentExecutionFacetIds.PathEnvironment, "list-path", AgentExecutionTargetContextWire.FromContext(context), cancellationToken);
    public async ValueTask AddPathEntryAsync(AgentExecutionTargetContext context, string executionPath, CancellationToken cancellationToken = default) => _ = await InvokeFacetAsync<ExecutionPathRequest, AgentRpcEmpty>(AgentExecutionFacetIds.PathEnvironment, "add-path", new(AgentExecutionTargetContextWire.FromContext(context), executionPath), cancellationToken).ConfigureAwait(false);
    public ValueTask<AgentFileSearchResult> ExecuteFileSearchAsync(AgentExecutionTargetContext context, AgentFileSearchRequest request, CancellationToken cancellationToken = default) => InvokeFacetAsync<ExecutionFileSearchRequest, AgentFileSearchResult>(AgentExecutionFacetIds.StructuredFileSearch, "structured-file-search", new(AgentExecutionTargetContextWire.FromContext(context), request), cancellationToken);
    public ValueTask<AgentScopedInstructionDiscoveryResult> DiscoverScopedInstructionsAsync(AgentExecutionTargetContext context, AgentScopedInstructionDiscoveryRequest request, CancellationToken cancellationToken = default) => InvokeFacetAsync<ExecutionInstructionDiscoveryRequest, AgentScopedInstructionDiscoveryResult>(AgentExecutionFacetIds.ScopedInstructionDiscovery, "discover-instructions", new(AgentExecutionTargetContextWire.FromContext(context), request), cancellationToken);

    private TResponse Invoke<TRequest, TResponse>(string method, TRequest request) where TRequest : notnull where TResponse : notnull => InvokeAsync<TRequest, TResponse>(method, request).AsTask().GetAwaiter().GetResult();
    private ValueTask<TResponse> InvokeAsync<TRequest, TResponse>(string method, TRequest request, CancellationToken token = default) where TRequest : notnull where TResponse : notnull => AgentRpcServiceHandler.InvokeAsync<TRequest, TResponse>(_client, _endpoint, AgentExecutionTargetRpc.ServiceId, method, request, token);
    private TResponse InvokeFacet<TRequest, TResponse>(string facet, string method, TRequest request) where TRequest : notnull where TResponse : notnull { RequireFacet(facet); return Invoke<TRequest, TResponse>(method, request); }
    private async ValueTask<TResponse> InvokeFacetAsync<TRequest, TResponse>(string facet, string method, TRequest request, CancellationToken token) where TRequest : notnull where TResponse : notnull
    {
        var descriptor = await DescribeAsync(token).ConfigureAwait(false);
        if (!descriptor.SupportsFacet(facet)) throw new NotSupportedException($"Execution target facet '{facet}' is not advertised.");
        return await InvokeAsync<TRequest, TResponse>(method, request, token).ConfigureAwait(false);
    }
    private void RequireFacet(string facet) { if (!Descriptor.SupportsFacet(facet)) throw new NotSupportedException($"Execution target facet '{facet}' is not advertised."); }
}

