public static class AgentSelectableCapabilityProviderRpc
{
    public const string ServiceId = "selectable-capability-provider";

    public static ISunderRpcServiceHandler CreateHandler(IAgentProfileSelectableCapabilityProvider provider)
        => AgentRpcServiceHandler.Create(AgentRpcContractDescriptors.Get(AgentRpcContractIds.SelectableCapabilityProvider))
            .AddUnary<AgentRpcEmpty, AgentRpcIdentity>(ServiceId, "describe", (_, _, _) => ValueTask.FromResult(new AgentRpcIdentity(provider.ProviderId, provider.DisplayName)))
            .AddUnary<AgentProfileSelectableCapabilityRequest, IReadOnlyList<AgentProfileSelectableCapabilityDescriptor>>(ServiceId, "list", (_, request, token) => provider.ListCapabilitiesAsync(request, token))
            .AddStream<AgentRpcEmpty, AgentRpcChange>(ServiceId, "watch", (_, _, token) => WatchSelectableCapabilities(provider, token))
            .Build();

    private static async IAsyncEnumerable<AgentRpcChange> WatchSelectableCapabilities(
        IAgentProfileSelectableCapabilityProvider provider,
        [EnumeratorCancellation] CancellationToken cancellationToken)
    {
        if (provider is not IAgentProfileSelectableCapabilityChangeNotifier notifier)
        {
            await Task.Delay(Timeout.InfiniteTimeSpan, cancellationToken).ConfigureAwait(false);
            yield break;
        }
        var channel = Channel.CreateBounded<AgentRpcChange>(new BoundedChannelOptions(1)
        {
            FullMode = BoundedChannelFullMode.DropOldest,
            SingleReader = true,
            SingleWriter = false,
        });
        long revision = 0;
        void Changed() => channel.Writer.TryWrite(new AgentRpcChange(Interlocked.Increment(ref revision)));
        notifier.SelectableCapabilitiesChanged += Changed;
        try
        {
            await foreach (var change in channel.Reader.ReadAllAsync(cancellationToken).ConfigureAwait(false)) yield return change;
        }
        finally
        {
            notifier.SelectableCapabilitiesChanged -= Changed;
            channel.Writer.TryComplete();
        }
    }
}

public sealed class AgentSelectableCapabilityProviderRpcClient : IAgentProfileSelectableCapabilityProvider, IAgentProfileSelectableCapabilityChangeNotifier, IDisposable
{
    private readonly ISunderRpcClient _client;
    private readonly SunderRpcEndpointReference _endpoint;
    private readonly CancellationTokenSource _lifetime = new();
    private readonly Task _watch;
    private AgentRpcIdentity? _identity;

    public AgentSelectableCapabilityProviderRpcClient(ISunderRpcClient client, SunderRpcEndpointReference endpoint)
    {
        _client = client;
        _endpoint = endpoint;
        _watch = WatchAsync();
    }

    private AgentRpcIdentity Identity => _identity ??= AgentRpcServiceHandler.InvokeAsync<AgentRpcEmpty, AgentRpcIdentity>(_client, _endpoint, AgentSelectableCapabilityProviderRpc.ServiceId, "describe", new AgentRpcEmpty()).AsTask().GetAwaiter().GetResult();
    public string ProviderId => Identity.Id;
    public string DisplayName => Identity.DisplayName;
    public event Action? SelectableCapabilitiesChanged;

    public ValueTask<IReadOnlyList<AgentProfileSelectableCapabilityDescriptor>> ListCapabilitiesAsync(AgentProfileSelectableCapabilityRequest request, CancellationToken cancellationToken = default)
        => AgentRpcServiceHandler.InvokeAsync<AgentProfileSelectableCapabilityRequest, IReadOnlyList<AgentProfileSelectableCapabilityDescriptor>>(_client, _endpoint, AgentSelectableCapabilityProviderRpc.ServiceId, "list", request, cancellationToken);

    public void Dispose()
    {
        _lifetime.Cancel();
        _ = _watch.ContinueWith(static (_, state) => ((CancellationTokenSource)state!).Dispose(), _lifetime, TaskScheduler.Default);
    }

    private async Task WatchAsync()
    {
        try
        {
            await foreach (var _ in AgentRpcServiceHandler.SubscribeAsync<AgentRpcEmpty, AgentRpcChange>(_client, _endpoint, AgentSelectableCapabilityProviderRpc.ServiceId, "watch", new AgentRpcEmpty(), _lifetime.Token).ConfigureAwait(false))
            {
                SelectableCapabilitiesChanged?.Invoke();
            }
        }
        catch (Exception exception) when (exception is OperationCanceledException or SunderRpcException)
        {
        }
    }
}

