public static class AgentRuntimeCatalogRpc
{
    private const int WatchCapacity = 256;
    public const string ServiceId = "runtime-catalog";

    public static ISunderRpcServiceHandler CreateHandler(IAgentRuntimeCatalog catalog)
        => AgentRpcServiceHandler.Create(AgentRpcContractDescriptors.Get(AgentRpcContractIds.RuntimeCatalog))
            .AddUnary<AgentRpcEmpty, IReadOnlyList<AgentSessionRecord>>(ServiceId, "list-sessions", (_, _, _) => ValueTask.FromResult(catalog.ListSessions()))
            .AddUnary<StringRequest, IReadOnlyList<AgentSessionRecord>>(ServiceId, "list-sessions-for-profile", (_, request, _) => ValueTask.FromResult(catalog.ListSessionsForProfile(request.Value)))
            .AddUnary<StringRequest, IReadOnlyList<AgentSessionRecord>>(ServiceId, "list-sessions-for-workspace", (_, request, _) => ValueTask.FromResult(catalog.ListSessionsForWorkspace(request.Value)))
            .AddNullableUnary<SessionIdRequest, AgentSessionRecord>(ServiceId, "get-session", (_, request, _) => ValueTask.FromResult(catalog.GetSession(request.SessionId)))
            .AddUnary<AgentRpcEmpty, IReadOnlyList<AgentWorkspaceRecord>>(ServiceId, "list-workspaces", (_, _, token) => catalog.ListWorkspacesAsync(token))
            .AddNullableUnary<StringRequest, AgentWorkspaceRecord>(ServiceId, "get-workspace", (_, request, token) => catalog.GetWorkspaceAsync(request.Value, token))
            .AddNullableUnary<SessionIdRequest, AgentProfileRecord>(ServiceId, "get-session-profile", (_, request, _) => ValueTask.FromResult(catalog.GetSessionProfile(request.SessionId)))
            .AddNullableUnary<SessionIdRequest, AgentWorkingSummaryRecord>(ServiceId, "get-working-summary", (_, request, _) => ValueTask.FromResult(catalog.GetWorkingSummary(request.SessionId)))
            .AddNullableUnary<SessionIdRequest, AgentSessionContextCheckpointRecord>(ServiceId, "get-session-context-checkpoint", (_, request, _) => ValueTask.FromResult(catalog.GetLatestSessionContextCheckpoint(request.SessionId)))
            .AddNullableUnary<SessionIdRequest, AgentRunCheckpointRecord>(ServiceId, "get-latest-checkpoint", (_, request, _) => ValueTask.FromResult(catalog.GetLatestCheckpoint(request.SessionId)))
            .AddUnary<RecentTurnsRequest, IReadOnlyList<AgentTurnRecord>>(ServiceId, "list-recent-turns", (_, request, _) => ValueTask.FromResult(catalog.ListRecentTurns(request.SessionId, request.Limit)))
            .AddUnary<TurnBoundaryRequest, IReadOnlyList<AgentTurnRecord>>(ServiceId, "list-turns-before", (_, request, _) => ValueTask.FromResult(catalog.ListTurnsBefore(request.SessionId, AgentRpcServiceHandler.FromWireTimestamp(request.CreatedAtUtc), request.TurnId, request.Limit)))
            .AddUnary<TurnBoundaryRequest, IReadOnlyList<AgentTurnRecord>>(ServiceId, "list-turns-after", (_, request, _) => ValueTask.FromResult(catalog.ListTurnsAfter(request.SessionId, AgentRpcServiceHandler.FromWireTimestamp(request.CreatedAtUtc), request.TurnId, request.Limit)))
            .AddUnary<RecentTurnsRequest, IReadOnlyList<AgentTurnRecord>>(ServiceId, "list-recent-transcript-headers", (_, request, _) => ValueTask.FromResult(
                catalog is IAgentTranscriptCatalog transcript
                    ? transcript.ListRecentTranscriptHeaders(request.SessionId, request.Limit)
                    : catalog.ListRecentTurns(request.SessionId, request.Limit)))
            .AddUnary<TurnBoundaryRequest, IReadOnlyList<AgentTurnRecord>>(ServiceId, "list-transcript-headers-before", (_, request, _) => ValueTask.FromResult(
                catalog is IAgentTranscriptCatalog transcript
                    ? transcript.ListTranscriptHeadersBefore(request.SessionId, AgentRpcServiceHandler.FromWireTimestamp(request.CreatedAtUtc), request.TurnId, request.Limit)
                    : catalog.ListTurnsBefore(request.SessionId, AgentRpcServiceHandler.FromWireTimestamp(request.CreatedAtUtc), request.TurnId, request.Limit)))
            .AddUnary<TurnBoundaryRequest, IReadOnlyList<AgentTurnRecord>>(ServiceId, "list-transcript-headers-after", (_, request, _) => ValueTask.FromResult(
                catalog is IAgentTranscriptCatalog transcript
                    ? transcript.ListTranscriptHeadersAfter(request.SessionId, AgentRpcServiceHandler.FromWireTimestamp(request.CreatedAtUtc), request.TurnId, request.Limit)
                    : catalog.ListTurnsAfter(request.SessionId, AgentRpcServiceHandler.FromWireTimestamp(request.CreatedAtUtc), request.TurnId, request.Limit)))
            .AddNullableUnary<AgentTranscriptToolDetailRequest, AgentTranscriptToolDetailRecord>(ServiceId, "get-transcript-tool-detail", (_, request, _) => ValueTask.FromResult(
                (catalog as IAgentTranscriptCatalog)?.GetTranscriptToolDetail(request)))
            .AddUnary<AgentRpcEmpty, IReadOnlyList<AgentProfileRecord>>(ServiceId, "list-profiles", (_, _, _) => ValueTask.FromResult(catalog.ListProfiles()))
            .AddNullableUnary<StringRequest, AgentProfileRecord>(ServiceId, "get-profile", (_, request, _) => ValueTask.FromResult(catalog.GetProfile(request.Value)))
            .AddNullableUnary<SessionCapabilityRequest, AgentProfileModelBindingRecord>(ServiceId, "get-session-model-binding", (_, request, _) => ValueTask.FromResult(catalog.GetSessionModelBinding(request.SessionId, request.CapabilityKind)))
            .AddNullableUnary<ProfileCapabilityRequest, AgentProfileModelBindingRecord>(ServiceId, "get-model-binding", (_, request, _) => ValueTask.FromResult(catalog.GetModelBinding(request.ProfileId, request.CapabilityKind)))
            .AddStream<AgentRpcEmpty, AgentRuntimeCatalogEvent>(ServiceId, "watch", (_, _, token) => WatchAsync(catalog, token))
            .Build();

    private static async IAsyncEnumerable<AgentRuntimeCatalogEvent> WatchAsync(
        IAgentRuntimeCatalog catalog,
        [EnumeratorCancellation] CancellationToken cancellationToken)
    {
        var channel = Channel.CreateBounded<AgentRuntimeCatalogEvent>(new BoundedChannelOptions(WatchCapacity)
        {
            FullMode = BoundedChannelFullMode.DropOldest,
            SingleReader = true,
            SingleWriter = false,
        });
        var publishSync = new object();
        long sequence = 0;
        void Publish(Func<long, AgentRuntimeCatalogEvent> create)
        {
            lock (publishSync)
            {
                channel.Writer.TryWrite(create(++sequence));
            }
        }
        void Session(Guid id) => Publish(next => new AgentSessionCatalogEvent(next, id));
        void Turn(Guid id, AgentTurnRecord turn) => Publish(next => new AgentTurnCatalogEvent(next, id, turn));
        void Profile(string id) => Publish(next => new AgentProfileCatalogEvent(next, id));
        void Reset() => Publish(next => new AgentRuntimeCatalogResetEvent(next));
        Publish(next => new AgentRuntimeCatalogResetEvent(next));
        catalog.SessionChanged += Session;
        catalog.TurnChanged += Turn;
        catalog.ProfileChanged += Profile;
        catalog.ResetRequired += Reset;
        try
        {
            var expectedSequence = 1L;
            await foreach (var item in channel.Reader.ReadAllAsync(cancellationToken).ConfigureAwait(false))
            {
                if (item.Sequence != expectedSequence)
                {
                    yield return new AgentRuntimeCatalogResetEvent(item.Sequence);
                }
                else
                {
                    yield return item;
                }
                expectedSequence = item.Sequence + 1;
            }
        }
        finally
        {
            catalog.SessionChanged -= Session;
            catalog.TurnChanged -= Turn;
            catalog.ProfileChanged -= Profile;
            catalog.ResetRequired -= Reset;
            channel.Writer.TryComplete();
        }
    }
}

public sealed class AgentRuntimeCatalogRpcClient :
    IAgentRuntimeCatalog,
    IAgentTranscriptCatalog,
    IDisposable
{
    private static readonly TimeSpan WatchRetryDelay = TimeSpan.FromMilliseconds(250);
    private readonly ISunderRpcClient _client;
    private readonly SunderRpcEndpointReference _endpoint;
    private readonly CancellationTokenSource _lifetime = new();
    private readonly Task _watch;

    public AgentRuntimeCatalogRpcClient(ISunderRpcClient client, SunderRpcEndpointReference endpoint)
    {
        _client = client;
        _endpoint = endpoint;
        _watch = WatchAsync();
    }

    public event Action<Guid>? SessionChanged;
    public event Action<Guid, AgentTurnRecord>? TurnChanged;
    public event Action<string>? ProfileChanged;
    public event Action? ResetRequired;

    public IReadOnlyList<AgentSessionRecord> ListSessions() => Invoke<AgentRpcEmpty, IReadOnlyList<AgentSessionRecord>>("list-sessions", new AgentRpcEmpty());
    public IReadOnlyList<AgentSessionRecord> ListSessionsForProfile(string profileId) => Invoke<StringRequest, IReadOnlyList<AgentSessionRecord>>("list-sessions-for-profile", new(profileId));
    public IReadOnlyList<AgentSessionRecord> ListSessionsForWorkspace(string workspaceId) => Invoke<StringRequest, IReadOnlyList<AgentSessionRecord>>("list-sessions-for-workspace", new(workspaceId));
    public AgentSessionRecord? GetSession(Guid sessionId) => InvokeNullable<SessionIdRequest, AgentSessionRecord>("get-session", new(sessionId));
    public async ValueTask<IReadOnlyList<AgentWorkspaceRecord>> ListWorkspacesAsync(
        CancellationToken cancellationToken = default)
    {
        using var invocation = CancellationTokenSource.CreateLinkedTokenSource(
            cancellationToken,
            _lifetime.Token);
        return await AgentRpcServiceHandler.InvokeAsync<AgentRpcEmpty, IReadOnlyList<AgentWorkspaceRecord>>(
            _client,
            _endpoint,
            AgentRuntimeCatalogRpc.ServiceId,
            "list-workspaces",
            new AgentRpcEmpty(),
            invocation.Token).ConfigureAwait(false);
    }

    public async ValueTask<AgentWorkspaceRecord?> GetWorkspaceAsync(
        string workspaceId,
        CancellationToken cancellationToken = default)
    {
        using var invocation = CancellationTokenSource.CreateLinkedTokenSource(
            cancellationToken,
            _lifetime.Token);
        return await AgentRpcServiceHandler.InvokeNullableAsync<StringRequest, AgentWorkspaceRecord>(
            _client,
            _endpoint,
            AgentRuntimeCatalogRpc.ServiceId,
            "get-workspace",
            new(workspaceId),
            invocation.Token).ConfigureAwait(false);
    }

    public AgentProfileRecord? GetSessionProfile(Guid sessionId) => InvokeNullable<SessionIdRequest, AgentProfileRecord>("get-session-profile", new(sessionId));
    public AgentWorkingSummaryRecord? GetWorkingSummary(Guid sessionId) => InvokeNullable<SessionIdRequest, AgentWorkingSummaryRecord>("get-working-summary", new(sessionId));
    public AgentSessionContextCheckpointRecord? GetLatestSessionContextCheckpoint(Guid sessionId) => InvokeNullable<SessionIdRequest, AgentSessionContextCheckpointRecord>("get-session-context-checkpoint", new(sessionId));
    public AgentRunCheckpointRecord? GetLatestCheckpoint(Guid sessionId) => InvokeNullable<SessionIdRequest, AgentRunCheckpointRecord>("get-latest-checkpoint", new(sessionId));
    public IReadOnlyList<AgentTurnRecord> ListRecentTurns(Guid sessionId, int limit) => Invoke<RecentTurnsRequest, IReadOnlyList<AgentTurnRecord>>("list-recent-turns", new(sessionId, limit));
    public IReadOnlyList<AgentTurnRecord> ListTurnsBefore(Guid sessionId, DateTimeOffset beforeCreatedAtUtc, Guid beforeTurnId, int limit) => Invoke<TurnBoundaryRequest, IReadOnlyList<AgentTurnRecord>>("list-turns-before", new(sessionId, AgentRpcServiceHandler.ToWireTimestamp(beforeCreatedAtUtc), beforeTurnId, limit));
    public IReadOnlyList<AgentTurnRecord> ListTurnsAfter(Guid sessionId, DateTimeOffset afterCreatedAtUtc, Guid afterTurnId, int limit) => Invoke<TurnBoundaryRequest, IReadOnlyList<AgentTurnRecord>>("list-turns-after", new(sessionId, AgentRpcServiceHandler.ToWireTimestamp(afterCreatedAtUtc), afterTurnId, limit));
    public IReadOnlyList<AgentTurnRecord> ListRecentTranscriptHeaders(Guid sessionId, int limit) => Invoke<RecentTurnsRequest, IReadOnlyList<AgentTurnRecord>>("list-recent-transcript-headers", new(sessionId, limit));
    public IReadOnlyList<AgentTurnRecord> ListTranscriptHeadersBefore(Guid sessionId, DateTimeOffset beforeCreatedAtUtc, Guid beforeTurnId, int limit) => Invoke<TurnBoundaryRequest, IReadOnlyList<AgentTurnRecord>>("list-transcript-headers-before", new(sessionId, AgentRpcServiceHandler.ToWireTimestamp(beforeCreatedAtUtc), beforeTurnId, limit));
    public IReadOnlyList<AgentTurnRecord> ListTranscriptHeadersAfter(Guid sessionId, DateTimeOffset afterCreatedAtUtc, Guid afterTurnId, int limit) => Invoke<TurnBoundaryRequest, IReadOnlyList<AgentTurnRecord>>("list-transcript-headers-after", new(sessionId, AgentRpcServiceHandler.ToWireTimestamp(afterCreatedAtUtc), afterTurnId, limit));
    public AgentTranscriptToolDetailRecord? GetTranscriptToolDetail(AgentTranscriptToolDetailRequest request) => InvokeNullable<AgentTranscriptToolDetailRequest, AgentTranscriptToolDetailRecord>("get-transcript-tool-detail", request);
    public IReadOnlyList<AgentProfileRecord> ListProfiles() => Invoke<AgentRpcEmpty, IReadOnlyList<AgentProfileRecord>>("list-profiles", new AgentRpcEmpty());
    public AgentProfileRecord? GetProfile(string profileId) => InvokeNullable<StringRequest, AgentProfileRecord>("get-profile", new(profileId));
    public AgentProfileModelBindingRecord? GetSessionModelBinding(Guid sessionId, string capabilityKind) => InvokeNullable<SessionCapabilityRequest, AgentProfileModelBindingRecord>("get-session-model-binding", new(sessionId, capabilityKind));
    public AgentProfileModelBindingRecord? GetModelBinding(string profileId, string capabilityKind) => InvokeNullable<ProfileCapabilityRequest, AgentProfileModelBindingRecord>("get-model-binding", new(profileId, capabilityKind));

    public void Dispose()
    {
        _lifetime.Cancel();
        _ = _watch.ContinueWith(static (_, state) => ((CancellationTokenSource)state!).Dispose(), _lifetime, TaskScheduler.Default);
    }

    private TResponse Invoke<TRequest, TResponse>(string methodId, TRequest request) where TRequest : notnull where TResponse : notnull
        => AgentRpcServiceHandler.InvokeAsync<TRequest, TResponse>(_client, _endpoint, AgentRuntimeCatalogRpc.ServiceId, methodId, request, _lifetime.Token).AsTask().GetAwaiter().GetResult();

    private TResponse? InvokeNullable<TRequest, TResponse>(string methodId, TRequest request) where TRequest : notnull where TResponse : class
        => AgentRpcServiceHandler.InvokeNullableAsync<TRequest, TResponse>(_client, _endpoint, AgentRuntimeCatalogRpc.ServiceId, methodId, request, _lifetime.Token).AsTask().GetAwaiter().GetResult();

    private async Task WatchAsync()
    {
        while (!_lifetime.IsCancellationRequested)
        {
            try
            {
                var expectedSequence = 1L;
                await foreach (var item in AgentRpcServiceHandler.SubscribeAsync<AgentRpcEmpty, AgentRuntimeCatalogEvent>(_client, _endpoint, AgentRuntimeCatalogRpc.ServiceId, "watch", new AgentRpcEmpty(), _lifetime.Token).ConfigureAwait(false))
                {
                    var continuityLost = item.Sequence != expectedSequence;
                    expectedSequence = item.Sequence + 1;
                    if (continuityLost && item is not AgentRuntimeCatalogResetEvent)
                    {
                        ResetRequired?.Invoke();
                    }

                    if (item is AgentRuntimeCatalogResetEvent) ResetRequired?.Invoke();
                    else if (item is AgentSessionCatalogEvent session) SessionChanged?.Invoke(session.SessionId);
                    else if (item is AgentTurnCatalogEvent turn) TurnChanged?.Invoke(turn.SessionId, turn.Turn);
                    else if (item is AgentProfileCatalogEvent profile) ProfileChanged?.Invoke(profile.ProfileId);
                }
            }
            catch (OperationCanceledException) when (_lifetime.IsCancellationRequested)
            {
                return;
            }
            catch (Exception exception) when (exception is OperationCanceledException or SunderRpcException)
            {
            }

            try
            {
                await Task.Delay(WatchRetryDelay, _lifetime.Token).ConfigureAwait(false);
            }
            catch (OperationCanceledException) when (_lifetime.IsCancellationRequested)
            {
                return;
            }
        }
    }
}

