[Sunder.Sdk.Packaging.SunderPackageCodeRole(Sunder.Sdk.Packaging.SunderPackageCodeRole.Shared)]
internal static class McpManagementPayload
{
    internal const int MaximumPayloadBytes = McpManagementContent.MaximumPayloadBytes;
    internal static async ValueTask<ManagementContent> RegisterRequestAsync<T>(ISunderRpcCallScope scope,
        SunderRpcEndpointReference endpoint, T value, string fileName, CancellationToken token) where T : notnull
        => new() { Content = await McpManagementContent.RegisterAsync(value, fileName, scope.DeadlineUtc,
            (stream, options, cancellation) => scope.RegisterContentAsync(endpoint, stream, options, cancellation), token).ConfigureAwait(false) };
    internal static async ValueTask<ManagementContent> RegisterResponseAsync<T>(SunderRpcInvocationContext context,
        T value, string fileName, CancellationToken token) where T : notnull
        => new() { Content = await McpManagementContent.RegisterResponseAsync(context, value, fileName, token).ConfigureAwait(false) };
    internal static ValueTask<T> ReadRequestAsync<T>(SunderRpcInvocationContext context, ManagementContent payload, CancellationToken token) where T : notnull
        => McpManagementContent.ReadRequestAsync<T>(context, payload.Content, token);
    internal static ValueTask<T> ReadResponseAsync<T>(ISunderRpcCallScope scope, ManagementContent payload, CancellationToken token) where T : notnull
        => McpManagementContent.ReadResponseAsync<T>(scope, payload.Content, token);
}

using System.Runtime.CompilerServices;
using Sunder.Package.Agent.Mcp.Protocol.Generated;
using Sunder.Package.Agent.Mcp.Services;
using Sunder.Sdk.Rpc;

namespace Sunder.Package.Agent.Mcp.Runtime;

internal sealed class McpManagementRpcProvider(
    McpRuntimeHandler operations,
    McpRuntimeChangeStream changes) : IManagementProvider
{
    public async ValueTask<ManagementContent> QueryAsync(
        SunderRpcInvocationContext context,
        ManagementContent request,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var query = await McpManagementPayload.ReadRequestAsync<McpQuery>(
                context,
                request,
                cancellationToken);
            var result = await operations.HandleAsync(query, cancellationToken);
            return await McpManagementPayload.RegisterResponseAsync(
                context,
                result,
                "mcp-projection.json",
                cancellationToken);
        }
        catch (Exception exception) when (ShouldMap(exception))
        {
            throw Failure((McpManagementOperationException)exception);
        }
    }

    public async ValueTask<ManagementContent> CommandAsync(
        SunderRpcInvocationContext context,
        ManagementContent request,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var command = await McpManagementPayload.ReadRequestAsync<McpCommand>(
                context,
                request,
                cancellationToken);
            var result = await operations.HandleAsync(command, cancellationToken);
            return await McpManagementPayload.RegisterResponseAsync(
                context,
                result,
                "mcp-projection.json",
                cancellationToken);
        }
        catch (Exception exception) when (ShouldMap(exception))
        {
            throw Failure((McpManagementOperationException)exception);
        }
    }

    public async IAsyncEnumerable<ManagementChange> ChangesAsync(
        SunderRpcInvocationContext context,
        ChangeSubscription request,
        [EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        yield return new ManagementChange { Kind = ManagementChangeKind.Servers };
        await foreach (var change in changes.WatchAsync(cancellationToken))
        {
            yield return new ManagementChange
            {
                Kind = change.Kind == McpChangeKind.Servers
                    ? ManagementChangeKind.Servers
                    : ManagementChangeKind.Status,
            };
        }
    }

    internal static bool ShouldMap(Exception exception)
        => exception is McpManagementOperationException;

    private static SunderRpcException Failure(McpManagementOperationException exception)
        => new(new SunderRpcError(
            SunderRpcErrorKind.Domain,
            "mcp.management.failed",
            exception.Message));
}

