internal sealed partial class MemoryAppRuntimeGateway
{
    private ValueTask<MemoryProjection> QueryTransportAsync(MemoryQuery request, CancellationToken token)
        => InvokeTransportAsync((client, cancellation) => client.QueryAsync(request, cancellation), token);
    private ValueTask<MemoryProjection> CommandTransportAsync(MemoryCommand request, CancellationToken token)
        => InvokeTransportAsync((client, cancellation) => client.CommandAsync(request, cancellation), token);

    private async ValueTask<MemoryProjection> InvokeTransportAsync(
        Func<MemoryInspectorRpcClient, CancellationToken, ValueTask<MemoryProjection>> invoke, CancellationToken token)
    {
        var provider = await ResolveProviderAsync(token).ConfigureAwait(false);
        await using var scope = await _rpc.CreateCallScopeAsync(cancellationToken: token).ConfigureAwait(false);
        return await invoke(MemoryInspectorRpc.CreateClient(scope, provider.Endpoint), token).ConfigureAwait(false);
    }

    private async IAsyncEnumerable<MemoryChanged> WatchTransportAsync([EnumeratorCancellation] CancellationToken token)
    {
        var provider = await ResolveProviderAsync(token).ConfigureAwait(false);
        await using var scope = await _rpc.CreateCallScopeAsync(cancellationToken: token).ConfigureAwait(false);
        var client = MemoryInspectorRpc.CreateClient(scope, provider.Endpoint);
        await foreach (var change in client.ChangesAsync(new MemoryChangeSubscription(), token).ConfigureAwait(false)) yield return change;
    }

    private async ValueTask<SunderRpcProviderSnapshot> ResolveProviderAsync(CancellationToken cancellationToken)
    {
        var descriptor = MemorySemanticProtocol.Inspector;
        var catalog = await _rpc.DiscoverAsync(descriptor.ContractId, cancellationToken).ConfigureAwait(false);
        var provider = catalog.Providers.SingleOrDefault(candidate =>
            candidate.ProviderId == MemorySemanticProtocol.ProviderId
            && candidate.State == SunderRpcProviderState.Active
            && candidate.ContractVersion == descriptor.Version
            && candidate.DescriptorSha256 == descriptor.Sha256
            && candidate.AbiSha256 == descriptor.AbiSha256);
        return provider ?? throw new SunderRpcException(new SunderRpcError(
            SunderRpcErrorKind.Unavailable,
            "semantic-memory.inspector-unavailable",
            "The semantic memory inspector Runtime provider is unavailable."));
    }
}

