namespace Sunder.Package.Agent.Memory.Semantic.Runtime;

internal sealed class LegacySemanticMemoryRpcCatalog : ISemanticMemoryRpcCatalog, IDisposable
{
    private readonly AgentRpcCatalog _catalog;

    internal LegacySemanticMemoryRpcCatalog(AgentRpcCatalog catalog)
    {
        _catalog = catalog;
        _catalog.Changed += OnChanged;
    }

    public event Action? Changed;
    public IReadOnlyList<SemanticProviderReference<IAgentRuntimeCatalog>> GetRuntimeCatalogs()
        => _catalog.GetServiceReferences(AgentRpcServices.RuntimeCatalogs).Select(value => (SemanticProviderReference<IAgentRuntimeCatalog>)new Reference<IAgentRuntimeCatalog>(value)).ToArray();
    public IReadOnlyList<SemanticProviderReference<IAgentEmbeddingProvider>> GetEmbeddingProviders()
        => _catalog.GetServiceReferences(AgentRpcServices.EmbeddingProviders).Select(value => (SemanticProviderReference<IAgentEmbeddingProvider>)new Reference<IAgentEmbeddingProvider>(value)).ToArray();
    public void Dispose() => _catalog.Changed -= OnChanged;

    private void OnChanged(object? sender, AgentRpcCatalogChangedEventArgs args)
    {
        if (args.IncludesContract(AgentRpcContractIds.RuntimeCatalog) || args.IncludesContract(AgentRpcContractIds.EmbeddingProvider)) Changed?.Invoke();
    }

    private sealed class Reference<T>(AgentRpcReference<T> reference) : SemanticProviderReference<T> where T : class
    {
        public override SunderRpcProviderSnapshot Provider => reference.Provider;
        public override bool TryAcquire([NotNullWhen(true)] out SemanticProviderLease<T>? lease)
        {
            if (!reference.TryAcquire(out var value)) { lease = null; return false; }
            lease = new(value.PackageId, value.Service, value.RetirementToken, value.Dispose);
            return true;
        }
    }
}

