internal sealed class MemoryWorkerComposition(IPackageContext context, ISunderRpcClient rpc) : IAsyncDisposable
{
    private ServiceProvider? _services;
    private SunderWorkerComposition? _composition;

    internal SunderWorkerOptions Configure(Action<IServiceCollection> configureTransport,
        Func<IServiceProvider, ISunderWorkerLifecycleService> transportLifecycle,
        Func<IServiceProvider, IReadOnlyList<SunderWorkerProviderRegistration>> createProviders)
    {
        if (_services is not null) throw new InvalidOperationException("Memory Worker composition has already been configured.");
        var services = new ServiceCollection();
        services.AddSingleton(context);
        services.AddSingleton(rpc);
        configureTransport(services);
        services.AddSingleton(_ => MemoryLocalStore.CreateDeferred(context));
        services.AddSingleton(_ => new MemorySemanticSettingsService(context));
        services.AddSingleton<SemanticMemoryMetricsService>();
        services.AddSingleton(provider => new SemanticModelRuntimeResolver(provider.GetRequiredService<ISemanticMemoryRpcCatalog>(),
            provider.GetRequiredService<MemorySemanticSettingsService>()));
        services.AddSingleton<SemanticMemoryRetrievalBackend>();
        services.AddSingleton<SemanticMemoryIndexingBackgroundService>();
        services.AddSingleton<SemanticMemoryRecallService>();
        services.AddSingleton<SemanticMemoryPromotionService>();
        services.AddSingleton<MemoryInspectorService>();
        services.AddSingleton<MemoryRuntimeHandler>();
        services.AddSingleton<MemorySemanticFeature>();
        _services = services.BuildServiceProvider(new ServiceProviderOptions { ValidateOnBuild = true, ValidateScopes = true });
        _composition = new SunderWorkerComposition(_services,
        [
            new StoreLifecycle(_services.GetRequiredService<MemoryLocalStore>()),
            transportLifecycle(_services),
            _services.GetRequiredService<SemanticMemoryIndexingBackgroundService>(),
        ]);
        return new SunderWorkerOptions(createProviders(_services))
        {
            SettingsSchema = MemorySemanticPackageConfiguration.Schema,
            Composition = _composition,
        };
    }

    public async ValueTask DisposeAsync()
    {
        if (_composition is not null) await _composition.DisposeAsync().ConfigureAwait(false);
        else if (_services is not null) await _services.DisposeAsync().ConfigureAwait(false);
    }

    private sealed class StoreLifecycle(MemoryLocalStore store) : ISunderWorkerLifecycleService
    {
        public Task Completion => Task.CompletedTask;
        public ValueTask PrepareCandidateAsync(CancellationToken cancellationToken = default)
        { cancellationToken.ThrowIfCancellationRequested(); return ValueTask.CompletedTask; }
        public ValueTask CommitGenerationAsync(SunderWorkerGenerationContext generation, CancellationToken cancellationToken = default)
        { cancellationToken.ThrowIfCancellationRequested(); return ValueTask.CompletedTask; }
        public ValueTask ActivateAsync(SunderWorkerContext context, CancellationToken cancellationToken = default)
        { store.Initialize(cancellationToken); return ValueTask.CompletedTask; }
        public ValueTask ShutdownAsync(SunderWorkerShutdownContext context, CancellationToken cancellationToken = default) => ValueTask.CompletedTask;
    }
}

