namespace Sunder.Package.Agent.Skills.Runtime;

internal sealed class LegacySkillsRuntimeBindings(AgentRpcCatalog catalog) : ISkillsRuntimeBindings
{
    public ValueTask StartAsync(CancellationToken cancellationToken = default)
    { cancellationToken.ThrowIfCancellationRequested(); catalog.StartWatching(); return ValueTask.CompletedTask; }

    public ValueTask<AgentProfileRecord?> GetProfileAsync(string? profileId, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        if (string.IsNullOrWhiteSpace(profileId)) return ValueTask.FromResult<AgentProfileRecord?>(null);
        foreach (var reference in catalog.GetServiceReferences(AgentRpcServices.RuntimeCatalogs))
        {
            if (!reference.TryAcquire(out var lease)) continue;
            using (lease)
            {
                var profile = lease.Service.GetProfile(profileId);
                if (!lease.RetirementToken.IsCancellationRequested) return ValueTask.FromResult(profile);
            }
        }
        return ValueTask.FromResult<AgentProfileRecord?>(null);
    }

    public async ValueTask<IReadOnlyList<AgentResolvedExecutionResource>> ResolveResourcesAsync(
        AgentExecutionTargetContext context, IReadOnlyList<AgentExecutionResourceDescriptor> resources,
        AgentRpcProviderHandle? selectedTarget, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        if (selectedTarget is null) return [];
        AgentRpcReference<IAgentExecutionTarget> reference;
        try { reference = catalog.GetServiceReference(AgentRpcServices.ExecutionTargets, selectedTarget); }
        catch (SunderRpcException error) when (error.Error.Kind is SunderRpcErrorKind.StaleEndpoint or SunderRpcErrorKind.Unavailable) { return []; }
        if (!reference.TryAcquire(out var lease)) return [];
        using (lease)
        {
            var retirement = lease.RetirementToken;
            if (retirement.IsCancellationRequested || !Matches(lease.Service.Descriptor, context.Binding)) return [];
            using var invocation = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken, retirement);
            try
            {
                var result = lease.Service.Descriptor.SupportsFacet(AgentExecutionFacetIds.ResourceResolution) && lease.Service is IAgentExecutionResourceResolver resolver
                    ? await resolver.ResolveResourcesAsync(context, resources, invocation.Token).ConfigureAwait(false) : [];
                return retirement.IsCancellationRequested && !cancellationToken.IsCancellationRequested ? [] : result;
            }
            catch (Exception error) when (!cancellationToken.IsCancellationRequested
                && (error is SunderRpcException { Error.Kind: SunderRpcErrorKind.StaleEndpoint or SunderRpcErrorKind.Unavailable }
                    || retirement.IsCancellationRequested && (error is OperationCanceledException || error is SunderRpcException { Error.Kind: SunderRpcErrorKind.Cancelled })))
            { return []; }
        }
    }

    private static bool Matches(AgentExecutionTargetDescriptor descriptor, AgentWorkspaceBindingRecord binding)
        => string.Equals(descriptor.TargetId, binding.ContributionId, StringComparison.OrdinalIgnoreCase)
           || string.Equals(descriptor.TargetKind, binding.ContributionId, StringComparison.OrdinalIgnoreCase);
    public ValueTask DisposeAsync() { catalog.Dispose(); return ValueTask.CompletedTask; }
}

