using Microsoft.Extensions.DependencyInjection;
using Sunder.Package.Agent.Skills.Services;
using Sunder.Sdk.Abstractions;
using Sunder.Sdk.Rpc;
using Sunder.Sdk.Worker;

namespace Sunder.Package.Agent.Skills.Runtime;

internal sealed class SkillsWorkerComposition(IPackageContext context, ISunderRpcClient rpc) : IAsyncDisposable
{
    private ServiceProvider? _services;
    private ISkillsRuntimeBindings? _runtime;
    private SkillRuntimeHandler? _handler;
    private readonly object _gate = new();
    private Task? _shutdown;
    internal IServiceProvider Services => _services ?? throw new InvalidOperationException("Skills Worker services have not been configured.");

    internal SunderWorkerOptions Configure(Action<IServiceCollection> configureTransport,
        Func<IServiceProvider, IReadOnlyList<SunderWorkerProviderRegistration>> createProviders)
    {
        if (_services is not null) throw new InvalidOperationException("Skills Worker composition has already been configured.");
        var services = new ServiceCollection();
        services.AddSingleton(context);
        services.AddSingleton(rpc);
        services.AddSingleton(_ => new HttpClient(new SocketsHttpHandler { AllowAutoRedirect = false })
        { BaseAddress = new Uri("https://api.github.com/"), Timeout = Timeout.InfiniteTimeSpan });
        services.AddSingleton<IGitHubSkillClient, GitHubSkillClient>();
        services.AddSingleton<SkillStore>();
        services.AddSingleton<SkillImportService>();
        services.AddSingleton(services => new SkillsFeature(services.GetRequiredService<SkillStore>(), services.GetRequiredService<ISkillsRuntimeBindings>()));
        services.AddSingleton<SkillStackContributor>();
        services.AddSingleton<SkillRuntimeHandler>();
        services.AddSingleton<SkillRuntimeChangeStream>();
        services.AddSingleton<SkillRuntimeOwnerClient>();
        configureTransport(services);
        _services = services.BuildServiceProvider(new ServiceProviderOptions { ValidateOnBuild = true, ValidateScopes = true });
        var store = _services.GetRequiredService<SkillStore>();
        _runtime = _services.GetRequiredService<ISkillsRuntimeBindings>();
        _handler = _services.GetRequiredService<SkillRuntimeHandler>();
        return new SunderWorkerOptions(createProviders(_services))
        {
            OnActivated = async (_, token) =>
            {
                token.ThrowIfCancellationRequested();
                store.Activate();
                await _handler.OrphanedTransferCleanup.WaitAsync(token).ConfigureAwait(false);
                await _runtime.StartAsync(token).ConfigureAwait(false);
            },
            OnShutdown = (_, _) => DisposeAsync(),
        };
    }

    public ValueTask DisposeAsync()
    {
        lock (_gate) return new(_shutdown ??= ShutdownAsync());
    }
    private async Task ShutdownAsync()
    {
        try
        {
            if (_runtime is not null) await _runtime.DisposeAsync().ConfigureAwait(false);
            if (_handler is not null) await _handler.StartedTransferCleanup.ConfigureAwait(false);
        }
        finally { if (_services is not null) await _services.DisposeAsync().ConfigureAwait(false); }
    }
}

