SubagentsWorkerComposition? owned = null;
try
{
    await SunderWorker.RunAsync(context =>
    {
        owned = new SubagentsWorkerComposition(context, context.Rpc);
        return owned.Configure(SubagentsWorkerBindings.ConfigureServices, SubagentsWorkerBindings.CreateProviders);
    });
}
finally { if (owned is not null) await owned.DisposeAsync(); }

