internal sealed class LegacySubagentRuntimeBindings(AgentRpcCatalog catalog) : ISubagentRuntimeBindings
{
    private readonly ConditionalWeakTable<AgentRpcReference<IAgentRuntimeCatalog>, Reference<IAgentRuntimeCatalog>> _catalogs = new();
    private readonly ConditionalWeakTable<AgentRpcReference<IAgentChildRunExecutor>, Reference<IAgentChildRunExecutor>> _children = new();
    private readonly ConditionalWeakTable<AgentRpcReference<IAgentChatProvider>, MappedReference<ISubagentChatCatalog>> _chats = new();
    private readonly ConditionalWeakTable<AgentRpcReference<IAgentToolSource>, MappedReference<ISubagentToolCatalog>> _tools = new();
    private readonly ConditionalWeakTable<AgentRpcReference<IAgentProfileSelectableCapabilityProvider>, Reference<IAgentProfileSelectableCapabilityProvider>> _capabilities = new();
    private readonly ConditionalWeakTable<AgentRpcProviderReference<IAgentBehaviorLoop>, MappedReference<ISubagentBehaviorCatalog>> _loops = new();
    private readonly object _gate = new();
    private Action? _changed;
    private Action<SubagentCatalogChange>? _catalogChanged;
    public event Action? RuntimeCatalogChanged
    {
        add { lock (_gate) { if (_changed is null && _catalogChanged is null) catalog.Changed += OnChanged; _changed += value; } }
        remove { lock (_gate) { _changed -= value; if (_changed is null && _catalogChanged is null) catalog.Changed -= OnChanged; } }
    }
    public event Action<SubagentCatalogChange>? CatalogChanged
    {
        add { lock (_gate) { if (_changed is null && _catalogChanged is null) catalog.Changed += OnChanged; _catalogChanged += value; } }
        remove { lock (_gate) { _catalogChanged -= value; if (_changed is null && _catalogChanged is null) catalog.Changed -= OnChanged; } }
    }
    private void OnChanged(object? sender, AgentRpcCatalogChangedEventArgs args)
    {
        var change = SubagentCatalogChange.None;
        if (args.IncludesContract(AgentRpcContractIds.RuntimeCatalog)) { change |= SubagentCatalogChange.RuntimeCatalog; _changed?.Invoke(); }
        if (args.IncludesContract(AgentRpcContractIds.ChatProvider)) change |= SubagentCatalogChange.ChatProviders;
        if (args.IncludesContract(AgentRpcContractIds.ToolSource)) change |= SubagentCatalogChange.Tools;
        if (args.IncludesContract(AgentRpcContractIds.SelectableCapabilityProvider)) change |= SubagentCatalogChange.SelectableCapabilities;
        if (args.IncludesContract(AgentRpcContractIds.BehaviorLoop)) change |= SubagentCatalogChange.BehaviorLoops;
        if (change != SubagentCatalogChange.None) _catalogChanged?.Invoke(change);
    }
    public ValueTask StartAsync(CancellationToken cancellationToken = default)
    { cancellationToken.ThrowIfCancellationRequested(); catalog.StartWatching(); return ValueTask.CompletedTask; }
    public IReadOnlyList<SubagentProviderReference<IAgentRuntimeCatalog>> GetRuntimeCatalogs()
        => catalog.GetServiceReferences(AgentRpcServices.RuntimeCatalogs).Select(value => (SubagentProviderReference<IAgentRuntimeCatalog>)_catalogs.GetValue(value, static reference => new(reference))).ToArray();
    public IReadOnlyList<SubagentProviderReference<IAgentChildRunExecutor>> GetChildRunExecutors()
        => catalog.GetServiceReferences(AgentRpcServices.ChildRunExecutors).Select(value => (SubagentProviderReference<IAgentChildRunExecutor>)_children.GetValue(value, static reference => new(reference))).ToArray();
    public ValueTask DisposeAsync()
    { lock (_gate) { catalog.Changed -= OnChanged; _changed = null; _catalogChanged = null; } return ValueTask.CompletedTask; }
    public IReadOnlyList<SubagentProviderReference<ISubagentChatCatalog>> GetChatProviders()
        => catalog.GetServiceReferences(AgentRpcServices.ChatProviders).Select(value => (SubagentProviderReference<ISubagentChatCatalog>)_chats.GetValue(value,
            static reference => new(reference.Provider, () => reference.TryAcquire(out var lease) ? new(lease.PackageId, new ChatCatalog(lease.Service), lease.RetirementToken, lease.Dispose) : null))).ToArray();
    public IReadOnlyList<SubagentProviderReference<ISubagentToolCatalog>> GetToolSources()
        => catalog.GetServiceReferences(AgentRpcServices.ToolSources).Select(value => (SubagentProviderReference<ISubagentToolCatalog>)_tools.GetValue(value,
            static reference => new(reference.Provider, () => reference.TryAcquire(out var lease) ? new(lease.PackageId, new ToolCatalog(lease.Service), lease.RetirementToken, lease.Dispose) : null))).ToArray();
    public IReadOnlyList<SubagentProviderReference<IAgentProfileSelectableCapabilityProvider>> GetSelectableCapabilityProviders()
        => catalog.GetServiceReferences(AgentRpcServices.SelectableCapabilityProviders).Select(value => (SubagentProviderReference<IAgentProfileSelectableCapabilityProvider>)_capabilities.GetValue(value, static reference => new(reference))).ToArray();
    public IReadOnlyList<SubagentProviderReference<ISubagentBehaviorCatalog>> GetBehaviorLoops()
        => catalog.GetServiceReferences(AgentRpcServices.CreateBehaviorLoops(new AgentRunControlRegistry(), catalog)).Select(value => (SubagentProviderReference<ISubagentBehaviorCatalog>)_loops.GetValue(value,
            static reference => new(reference.Provider, () => reference.TryAcquire(out var lease) ? new(lease.PackageId, new BehaviorCatalog(lease.Service), lease.RetirementToken, lease.Dispose) : null))).ToArray();
    internal static SubagentProviderReference<T> Wrap<T>(AgentRpcReference<T> reference) where T : class => new Reference<T>(reference);

    private sealed class Reference<T>(AgentRpcReference<T> reference) : SubagentProviderReference<T> where T : class
    {
        public override SunderRpcProviderSnapshot Provider => reference.Provider;
        public override bool TryAcquire([NotNullWhen(true)] out SubagentProviderLease<T>? lease)
        {
            if (!reference.TryAcquire(out var value)) { lease = null; return false; }
            lease = new(value.PackageId, value.Service, value.RetirementToken, value.Dispose);
            return true;
        }
    }
    private sealed class MappedReference<T>(SunderRpcProviderSnapshot provider, Func<SubagentProviderLease<T>?> acquire) : SubagentProviderReference<T> where T : class
    {
        public override SunderRpcProviderSnapshot Provider => provider;
        public override bool TryAcquire([NotNullWhen(true)] out SubagentProviderLease<T>? lease) { lease = acquire(); return lease is not null; }
    }
    private sealed class ChatCatalog(IAgentChatProvider provider) : ISubagentChatCatalog
    {
        public AgentProviderDescriptor Descriptor => provider.Descriptor;
        public ValueTask<IReadOnlyList<AgentModelDescriptor>> GetAvailableModelsAsync(CancellationToken token = default) => provider.GetAvailableModelsAsync(token);
        public ValueTask<AgentProviderReadiness> GetReadinessAsync(CancellationToken token = default) => provider.GetReadinessAsync(token);
    }
    private sealed class ToolCatalog(IAgentToolSource source) : ISubagentToolCatalog
    {
        public string SourceId => source.SourceId;
        public string DisplayName => source.DisplayName;
        public ValueTask<IReadOnlyList<AgentToolDescriptor>> ListToolsAsync(AgentToolSourceContext context, CancellationToken token = default) => source.ListToolsAsync(context, token);
    }
    private sealed class BehaviorCatalog(IAgentBehaviorLoop loop) : ISubagentBehaviorCatalog
    { public AgentBehaviorLoopDescriptor Descriptor => loop.Descriptor; }
}

