namespace Sunder.Package.Agent.Subagents.Runtime;

internal static class SubagentsWorkerBindings
{
    internal static void ConfigureServices(IServiceCollection services)
    {
        services.AddSingleton(services => AgentRpcCatalog.CreateDormant(services.GetRequiredService<ISunderRpcClient>()));
        services.AddSingleton<ISubagentRuntimeBindings, LegacySubagentRuntimeBindings>();
        services.AddSingleton(services => new SubagentOwnerProvider(services.GetRequiredService<ISubagentOwnerClient>()));
    }
    internal static IReadOnlyList<SunderWorkerProviderRegistration> CreateProviders(IServiceProvider services)
    {
        var feature = services.GetRequiredService<SubagentFeature>();
        return
        [
            Register("subagents.selectable.capabilities", AgentRpcContractDescriptors.Get(AgentRpcContractIds.SelectableCapabilityProvider), AgentSelectableCapabilityProviderRpc.CreateHandler(feature)),
