using Microsoft.Extensions.DependencyInjection;
using Sunder.Package.Agent.Subagents.Services;
using Sunder.Sdk.Abstractions;
using Sunder.Sdk.Rpc;
using Sunder.Sdk.Worker;

namespace Sunder.Package.Agent.Subagents.Runtime;

internal sealed class SubagentsWorkerComposition(IPackageContext context, ISunderRpcClient rpc) : IAsyncDisposable
{
    private ServiceProvider? _services;
    private ISubagentRuntimeBindings? _runtimeBindings;
    private readonly object _gate = new();
    private Task? _shutdown;
    internal IServiceProvider Services => _services ?? throw new InvalidOperationException("Subagents Worker services have not been configured.");

    internal SunderWorkerOptions Configure(Action<IServiceCollection> configureTransport,
        Func<IServiceProvider, IReadOnlyList<SunderWorkerProviderRegistration>> createProviders)
    {
        if (_services is not null) throw new InvalidOperationException("Subagents Worker composition has already been configured.");
        var services = new ServiceCollection();
        services.AddSingleton(context);
        services.AddSingleton(rpc);
        services.AddSingleton<SubagentStore>();
        services.AddSingleton<SubagentService>();
        services.AddSingleton(services => new SubagentFeature(services.GetRequiredService<SubagentService>(), services.GetRequiredService<ISubagentRuntimeBindings>()));
        services.AddSingleton<OrchestratedAgentBehaviorLoop>();
        services.AddSingleton(services => new SubagentStackContributor(services.GetRequiredService<SubagentService>(), context, services.GetRequiredService<ISubagentRuntimeBindings>()));
        services.AddSingleton(services => new SubagentRuntimeHandler(services.GetRequiredService<SubagentService>(), services.GetRequiredService<ISubagentRuntimeBindings>()));
        services.AddSingleton(services => new SubagentRuntimeChangeStream(services.GetRequiredService<SubagentService>(), services.GetRequiredService<ISubagentRuntimeBindings>()));
        services.AddSingleton<SubagentRuntimeOwnerClient>();
        services.AddSingleton<ISubagentOwnerClient, ActivatedOwnerClient>();
        configureTransport(services);
        _services = services.BuildServiceProvider(new ServiceProviderOptions { ValidateOnBuild = true, ValidateScopes = true });
        var store = _services.GetRequiredService<SubagentStore>();
        _runtimeBindings = _services.GetRequiredService<ISubagentRuntimeBindings>();
        return new SunderWorkerOptions(createProviders(_services))
        {
            OnActivated = async (_, token) =>
            {
                token.ThrowIfCancellationRequested();
                store.Activate();
                await _runtimeBindings.StartAsync(token).ConfigureAwait(false);
                // Legacy catalog listeners make synchronous RPC calls while being
                // constructed. Yield the Worker reader so it can process replies.
                await Task.Run(() => _services.GetRequiredService<SubagentRuntimeOwnerClient>(), token).ConfigureAwait(false);
            },
            OnShutdown = (_, _) => DisposeAsync(),
        };
    }

    public ValueTask DisposeAsync()
    {
        lock (_gate) return new(_shutdown ??= ShutdownAsync());
    }
    private async Task ShutdownAsync()
    {
        try
        {
            if (_runtimeBindings is not null) await _runtimeBindings.DisposeAsync().ConfigureAwait(false);
        }
        finally { if (_services is not null) await _services.DisposeAsync().ConfigureAwait(false); }
    }

    // Provider metadata can be declared before Runtime subscriptions exist.
    private sealed class ActivatedOwnerClient(IServiceProvider services) : ISubagentOwnerClient
    {
        private ISubagentOwnerClient Operations => services.GetRequiredService<SubagentRuntimeOwnerClient>();
        public ValueTask<SubagentProjection> QueryAsync(SubagentQuery request, CancellationToken token = default) => Operations.QueryAsync(request, token);
        public ValueTask<SubagentProjection> CommandAsync(SubagentCommand request, CancellationToken token = default) => Operations.CommandAsync(request, token);
        public IAsyncEnumerable<SubagentChanged> SubscribeChangesAsync(SubagentChangeSubscription request, CancellationToken token = default) => Operations.SubscribeChangesAsync(request, token);
    }
}

