internal sealed class FilesWorkerComposition : IAsyncDisposable
{
    private readonly ServiceProvider _services;
    private readonly IFilesRuntimeBindings _bindings;
    private readonly object _gate = new();
    private Task? _dispose;

    internal FilesWorkerComposition(IPackageContext context, ISunderRpcClient rpc)
    {
        var services = new ServiceCollection();
        services.AddSingleton(context);
        services.AddSingleton<FilesToolSource>();
        FilesWorkerBindings.ConfigureServices(services, rpc);
        _services = services.BuildServiceProvider(new ServiceProviderOptions { ValidateOnBuild = true, ValidateScopes = true });
        _bindings = _services.GetRequiredService<IFilesRuntimeBindings>();
        try
        {
            var source = _services.GetRequiredService<FilesToolSource>();
            Options = new(FilesWorkerBindings.CreateProviders(_services))
            {
                OnActivated = (_, token) => { source.Activate(); return _bindings.StartAsync(token); },
                OnShutdown = (_, _) => DisposeAsync(),
            };
        }
        catch { _services.DisposeAsync().AsTask().GetAwaiter().GetResult(); throw; }
    }

    internal SunderWorkerOptions Options { get; }
    public ValueTask DisposeAsync()
    {
        lock (_gate) return new(_dispose ??= DisposeCoreAsync());
    }
    private async Task DisposeCoreAsync()
    {
        try { await _bindings.DisposeAsync().ConfigureAwait(false); }
        finally { await _services.DisposeAsync().ConfigureAwait(false); }
    }
}

